# Usage: python svs.py \
#   --ref_audio_jsonl /path/to/reference/audio.jsonl \
#   --gen_audio_jsonl /path/to/generated/audio.jsonl \
#   --output_file /path/to/output/directory/result.txt \
#   --c 16
# where `gen_dir` can be generated by `generate_postprocess/make_audio_jsonl.py`
import torch
